uptime; cd /var/opt/mgu-deploy; for f in last-shutdown safe-mode-count restart-requested safe-mode-crashes; do echo "== $f $(ls -la --full-time $f 2>/dev/null | awk "{print \$6,\$7}")"; cat $f; echo; done; ls -la /var/opt/mgu-deploy/safe-mode 2>&1; echo ---; ls -la /var/opt/devlink-wifi; echo ---; systemctl is-active devlink-wifilog mgu-uplink; systemctl status mgu-uplink --no-pager 2>&1 | head -12 | cut -c1-180; echo ---; systemctl --failed --no-pager 2>&1 | head -15; echo ---; ls -lat /var/crash /var/opt/crash* /var/core* /var/opt/sys/crash* 2>/dev/null | head -15; journalctl -b --no-pager -o short-iso 2>/dev/null | grep -i -E "devlink|core dump|crash|restart.*head|reset reason|wakeup|shutdown" | tail -25 | cut -c1-220
